INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4136800, 593457, 83313, '<td valign="top">Just a macro of a PCB, but I think it''s well done. Lighting, colors and focus are all spot on. The angled shot helps this as well.</td>', 'Just a macro of a PCB, but I think it''s well done. Lighting, colors and focus are all spot on. The angled shot helps this as well.', '2007-10-03 10:20:14.000000', NULL, 1),
(4136817, 594338, 83313, '<td valign="top">Very clear.</td>', 'Very clear.', '2007-10-03 10:23:08.000000', NULL, 1),
(4136832, 594838, 83313, '<td valign="top">Nice skin tones, lighting and all around look. Some careful prep work went into this.</td>', 'Nice skin tones, lighting and all around look. Some careful prep work went into this.', '2007-10-03 10:25:11.000000', NULL, 1),
(4136835, 594659, 84400, '<td valign="top">I like!</td>', 'I like!', '2007-10-03 10:25:28.000000', NULL, 1),
