(4140467, 593905, 33515, '<td valign="top">I''m never a big fan of toy shots but the lighting and attention to small details (the footsteps) makes this better than average. At least it''s not a Woody!</td>', 'I''m never a big fan of toy shots but the lighting and attention to small details (the footsteps) makes this better than average. At least it''s not a Woody!', '2007-10-04 09:24:48.000000', NULL, 1),
(4140540, 594728, 33515, '<td valign="top">Nice entry, I like the wide angle. The top right seems a little empty considering the other sides are cropped so tight.</td>', 'Nice entry, I like the wide angle. The top right seems a little empty considering the other sides are cropped so tight.', '2007-10-04 09:41:23.000000', NULL, 1),
(4140548, 594891, 33515, '<td valign="top">Have you seen those tee shirt with the blurred words like "I''ve had to much coffee" or whatever. This picture makes me feel light headed, like one of those shirts, and I can''t look at it for very long.</td>', 'Have you seen those tee shirt with the blurred words like "I''ve had to much coffee" or whatever. This picture makes me feel light headed, like one of those shirts, and I can''t look at it for very long.', '2007-10-04 09:44:25.000000', NULL, 1),
(4140556, 594771, 33515, '<td valign="top">There are really to many shadows for this to be great. Nice composition otherwise.</td>', 'There are really to many shadows for this to be great. Nice composition otherwise.', '2007-10-04 09:45:54.000000', NULL, 1),
(4140562, 594348, 33515, '<td valign="top">The processing work overwhelms what the picture should be of.</td>', 'The processing work overwhelms what the picture should be of.', '2007-10-04 09:47:33.000000', NULL, 1),
(4140566, 592572, 33515, '<td valign="top">If you could have kept the detail in the moon this would have been very nice.</td>', 'If you could have kept the detail in the moon this would have been very nice.', '2007-10-04 09:48:37.000000', NULL, 1),
(4140577, 593900, 44628, '<td valign="top">Very poignant</td>', 'Very poignant', '2007-10-04 09:51:46.000000', NULL, 1),
(4140581, 594157, 33515, '<td valign="top">Had to look that up to see what is was, thanks for the education. <br/>Nice photo, but there isn''t anything about it that really jumps off the screen. I don''t have any ideas how to improve it.</td>', 'Had to look that up to see what is was, thanks for the education. Nice photo, but there isn''t anything about it that really jumps off the screen. I don''t have any ideas how to improve it.', '2007-10-04 09:53:15.000000', NULL, 1),
