(4151443, 593249, 79720, '<td valign="top">The harsh lighting did not help. I think a side-light, black background would have made this image really good.</td>', 'The harsh lighting did not help. I think a side-light, black background would have made this image really good.', '2007-10-08 10:22:34.000000', NULL, 1),
(4151446, 592566, 79720, '<td valign="top">Yikes. Is that how we''re treating our EOS''s these days? Must be a Nikon fan. <b>:</b>-)</td>', 'Yikes. Is that how we''re treating our EOS''s these days? Must be a Nikon fan. :-)', '2007-10-08 10:23:22.000000', NULL, 1),
(4151448, 593105, 79720, '<td valign="top">I like your use of the RoT, and the lines are great.</td>', 'I like your use of the RoT, and the lines are great.', '2007-10-08 10:23:59.000000', NULL, 1),
(4151449, 594728, 79720, '<td valign="top">Cool lighting, and wicked DoF on such a macro-ish composition.</td>', 'Cool lighting, and wicked DoF on such a macro-ish composition.', '2007-10-08 10:25:25.000000', NULL, 1),
(4151452, 594279, 79720, '<td valign="top">haha! Clever. Too bad she isn''t giving a topless cam-show.</td>', 'haha! Clever. Too bad she isn''t giving a topless cam-show.', '2007-10-08 10:26:13.000000', NULL, 1),
(4151455, 592028, 79720, '<td valign="top">hmmmm. Interesting perspective, nice colours, but something got lost in the post-processing step. Lines seem too jagged.</td>', 'hmmmm. Interesting perspective, nice colours, but something got lost in the post-processing step. Lines seem too jagged.', '2007-10-08 10:27:10.000000', NULL, 1),
(4151457, 592730, 79720, '<td valign="top">Nice colours, a little busy perhaps. The hammer is lost in the composition. "Percussive Maintenance" should have been the title.</td>', 'Nice colours, a little busy perhaps. The hammer is lost in the composition. "Percussive Maintenance" should have been the title.', '2007-10-08 10:28:01.000000', NULL, 1),
