(4154616, 594338, 3746, '<td valign="top">Dont try to force an image into a challenge by means of a title. really, this DNMC in any way.</td>', 'Dont try to force an image into a challenge by means of a title. really, this DNMC in any way.', '2007-10-09 14:33:56.000000', NULL, 1),
(4154661, 591878, 3746, '<td valign="top">This is amazing, my pick for the top.. great use of light &amp; shadow, the juxtaposition between old style gaming and technology (in the timepiece) is truely imspiring.. 10 all the way!!<br/> <br/> <br/>well done whiterook!</td>', 'This is amazing, my pick for the top.. great use of light & shadow, the juxtaposition between old style gaming and technology (in the timepiece) is truely imspiring.. 10 all the way!!  well done whiterook!', '2007-10-09 15:02:05.000000', NULL, 1),
(4154675, 594506, 3746, '<td valign="top">top 5. maybe top 3.. 8<br/> <br/>back again - bumping to a ten, should win the challenge.</td>', 'top 5. maybe top 3.. 8 back again - bumping to a ten, should win the challenge.', '2007-10-09 15:05:56.000000', NULL, 1),
(4154676, 594273, 16062, '<td valign="top">I like the concept but the image itself is somewhat uninspired.  Somewhat lacking in contrast, a little too much sharpening, a little noisy.  The way the top of the calculator and the bottom of the bill just barely extends past the frame is bothering me- it''s like the crop was left to chance, not deliberate enough.  Sorry for being so harsh, hope it''s at least somewhat helpful.  I hate it when my images get low votes with no explanation.</td>', 'I like the concept but the image itself is somewhat uninspired.  Somewhat lacking in contrast, a little too much sharpening, a little noisy.  The way the top of the calculator and the bottom of the bill just barely extends past the frame is bothering me- it''s like the crop was left to chance, not deliberate enough.  Sorry for being so harsh, hope it''s at least somewhat helpful.  I hate it when my images get low votes with no explanation.', '2007-10-09 15:05:57.000000', NULL, 1),
(4154680, 594755, 16062, '<td valign="top">looks like maybe some camera shake occurred at 7:27</td>', 'looks like maybe some camera shake occurred at 7:27', '2007-10-09 15:07:52.000000', NULL, 1),
(4154710, 593170, 16062, '<td valign="top">get outta here!  That''s the coolest part!</td>', 'get outta here!  That''s the coolest part!', '2007-10-09 15:21:49.000000', NULL, 1),
(4154716, 593475, 16062, '<td valign="top">bravo!  Excellent idea  ...Of course the other shot for this title would have featured a little person inside the screen working at a little computer monitor...</td>', 'bravo!  Excellent idea  ...Of course the other shot for this title would have featured a little person inside the screen working at a little computer monitor...', '2007-10-09 15:25:04.000000', NULL, 1),
